<?php require_once __DIR__.'/includes/bootstrap.php';if(current_user()){ $dest=(($_GET['return']??'')==='checkout.php')?'checkout.php':(current_user()['role']==='admin'?'admin.php':'client.php'); redirect($dest); }$error='';if(is_post()){verify_csrf();public_form_guard($db, 'login', $_POST['recaptcha_token'] ?? '');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(auth_rate_limited($db,$email)){ $error='Too many failed attempts. Please wait 15 minutes and try again.'; } elseif($db){$st=$db->prepare('SELECT id,email,password_hash,full_name,role,account_balance FROM users WHERE email=? LIMIT 1');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['wdh_user']=$u;
if($db){try{$st=$db->prepare('UPDATE users SET last_login_at=NOW(), last_login_ip=? WHERE id=?');$st->execute([substr((string)($_SERVER['REMOTE_ADDR']??''),0,45),(int)$u['id']]);record_login_activity($db,(int)$u['id'],'login_success');}catch(Throwable $e){}}
auth_rate_clear($db,$email); $dest=(($_GET['return']??'')==='checkout.php' && $u['role']!=='admin')?'checkout.php':($u['role']==='admin'?'admin.php':'client.php'); redirect($dest);}}if($db && isset($u['id'])){record_login_activity($db,(int)$u['id'],'login_failed');}auth_rate_record_failure($db,$email);$error='Invalid email or password.';}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="auth-page"><form class="auth-card" method="post"><h1>Welcome Back</h1><p>Sign in to your WDH account.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('login')?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn primary">Login</button><p>Don't have an account? <a href="signup.php">Create one</a></p></form></main><?php require __DIR__.'/includes/footer.php';?></body></html>
